module baud_gen (
    input clk, rst,
    input [7:0] div,
    output tick
);
reg [7:0] counter;
    reg tick;
    always @(posedge clk) begin
        if (rst) begin
            counter <= 8'b0;
            tick <= 1'b0;
        end
        else begin
            if (counter == div - 1) begin
                counter <= 8'b0;
                tick <= 1'b1;
            end
            else begin
                counter <= counter + 1'b1;
                tick <= 1'b0;
            end
        end
    end
    assign tick = counter == div - 1;
endmodule

