module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);
reg [WIDTH-1:0]   mem[0:DEPTH-1];
reg [31:0]        wr_ptr;
reg [31:0]        rd_ptr;
reg [31:0]        word_count;
reg                full_p;
reg                empty_p;
reg                prog_full_p;
reg                overflow_p;
reg                underflow_p;

always @(posedge clk)
begin
    if (reset_p)
    begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        word_count <= 0;
        full_p <= 0;
        empty_p <= 1;
        prog_full_p <= 0;
        overflow_p <= 0;
        underflow_p <= 0;
    end
    else
    begin
        if (data_we)
        begin
            if (word_count < DEPTH)
            begin
                mem[wr_ptr] <= data_i;
                wr_ptr <= wr_ptr + 1;
                word_count <= word_count + 1;
                full_p <= 0;
                empty_p <= 0;
                prog_full_p <= 0;
                overflow_p <= 0;
                underflow_p <= 0;
            end
            else
            begin
                overflow_p <= 1;
                underflow_p <= 0;
            end
        end
        if (data_rd)
        begin
            if (word_count > 0)
            begin
                rd_ptr <= rd_ptr + 1;
                word_count <= word_count - 1;
                full_p <= 0;
                empty_p <= 0;
                prog_full_p <= 0;
                overflow_p <= 0;
                underflow_p <= 0;
            end
            else
            begin
                overflow_p <= 0;
                underflow_p <= 1;
            end
        end
        if (data_we && data_rd)
        begin
            if (word_count < DEPTH)
            begin
                full_p <= 0;
                empty_p <= 0;
                prog_full_p <= 0;
                overflow_p <= 0;
                underflow_p <= 0;
            end
            else
            begin
                full_p <= 1;
                empty_p <= 0;
                prog_full_p <= 0;
                overflow_p <= 0;
                underflow_p <= 0;
            end
        end
        if (data_we && data_rd && word_count < DEPTH)
        begin
            full_p <= 0;
            empty_p <= 0;
            prog_full_p <= 0;
            overflow_p <= 0;
            underflow_p <= 0;
        end
        if (data_we && data_rd && word_count == DEPTH)
        begin
            full_p <= 0;
            empty_p <= 0;
            prog_full_p <= 0;
            overflow_p <= 0;
            underflow_p <= 0;
        end
        if (data_we && data_rd && word_count > DEPTH)
        begin
            full_p <= 0;
            empty_p <= 0;
            prog_full_p <= 0;
            overflow_p <= 0;
            underflow_p <= 0;
        end
        if (data_we && data_rd && word_count == 0)
        begin
            full_p <= 0;
            empty_p <= 0;
            prog_full_p <= 0;
            overflow_p <= 0;
            underflow_p <= 0;
        end
        if (data_we && data_rd && word_count < PROG_FULL)
        begin
            prog_full_p <= 0;
            overflow_p <= 0;
            underflow_p <= 0;
        end
        if (data_we && data_rd && word_count == PROG_FULL)
        begin
            prog_full_p <= 1;
            overflow_p <= 0;
            underflow_p <= 0;
        end
        if (data_we && data_rd && word_count > PROG_FULL)
        begin
            prog_full_p <= 0;
            overflow_p <= 0;
            underflow_p <= 0;
        end
        if (data_we && data_rd && word_count == 0)
        begin
            prog_full_p <= 0;
            overflow_p <= 0;
            underflow_p <= 0;
        end
    end
end

assign data_o = mem[rd_ptr];

assign prog_full = prog_full_p;
assign full = full_p;
assign empty = empty_p;
assign overflow = overflow_p;
assign underflow = underflow_p;

endmodule

