weight_alert = 1'b0;
end
else if (over_time == 1'b1) begin
out_current_floor = 8'b00000000;
direction = 1'b0;
complete = 1'b0;
door_alert = 1'b1;
weight_alert = 1'b0;
end
else if (over_weight == 1'b1) begin
out_current_floor = 8'b00000000;
direction = 1'b0;
complete = 1'b0;
door_alert = 1'b0;
weight_alert = 1'b1;
end
else if (request_floor == out_current_floor) begin
out_current_floor = 8'b00000000;
direction = 1'b0;
complete = 1'b1;
door_alert = 1'b0;
weight_alert = 1'b0;
end
else if (request_floor > out_current_floor) begin
out_current_floor = out_current_floor + 1;
direction = 1'b1;
complete = 1'b0;
door_alert = 1'b0;
weight_alert = 1'b0;
end
else if (request_floor < out_current_floor) begin
out_current_floor = out_current_floor - 1;
direction = 1'b0;
complete = 1'b0;
door_alert = 1'b0;
weight_alert = 1'b0;
end
end

endmodule

