    case(shiftAlufn)
      2'b00: shiftOut = {16{1'b0}};
      2'b01: shiftOut = {16{1'b0}};
      2'b10: shiftOut = {16{1'b0}};
      2'b11: shiftOut = {16{1'b0}};
      default: shiftOut = {16{1'b0}};
    endcase
  end
  always @* begin
    reg [15:0] temp;
    case(shiftAlufn)
      2'b00: temp = x << y[3:0];
      2'b01: temp = x >> y[3:0];
      2'b10: temp = x << y[3:0];
      2'b11: temp = x >> y[3:0];
      default: temp = {16{1'b0}};
    endcase
    shiftOut = temp;
  end
endmodule

