module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
reg [1:0] state;
  reg src0_rdy_o, src1_rdy_o;
  reg eof;
  reg [35:0] data0_o, data1_o;
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      src0_rdy_o <= 1'b0;
      src1_rdy_o <= 1'b0;
      eof <= 1'b0;
    end else begin
      case (state)
        2'b00: begin
          if (src_rdy_i) begin
            if (data_i[35:0] == match_data && data_i[35:0] == match_mask) begin
              state <= 2'b01;
              src0_rdy_o <= 1'b1;
              src1_rdy_o <= 1'b0;
              eof <= 1'b0;
            end else begin
              state <= 2'b00;
              src0_rdy_o <= 1'b0;
              src1_rdy_o <= 1'b0;
              eof <= 1'b0;
            end
          end else begin
            state <= 2'b00;
            src0_rdy_o <= 1'b0;
            src1_rdy_o <= 1'b0;
            eof <= 1'b0;
          end
        end
        2'b01: begin
          if (dst0_rdy_i) begin
            if (eof) begin
              state <= 2'b00;
              src0_rdy_o <= 1'b0;
              src1_rdy_o <= 1'b0;
            end else begin
              state <= 2'b01;
              src0_rdy_o <= 1'b1;
              src1_rdy_o <= 1'b0;
            end
          end else begin
            state <= 2'b01;
            src0_rdy_o <= 1'b0;
            src1_rdy_o <= 1'b0;
          end
        end
        2'b10: begin
          if (dst1_rdy_i) begin
            if (eof) begin
              state <= 2'b00;
              src0_rdy_o <= 1'b0;
              src1_rdy_o <= 1'b0;
            end else begin
              state <= 2'b10;
              src0_rdy_o <= 1'b0;
              src1_rdy_o <= 1'b1;
            end
          end else begin
            state <= 2'b10;
            src0_rdy_o <= 1'b0;
            src1_rdy_o <= 1'b0;
          end
        end
        default: begin
          state <= 2'b00;
          src0_rdy_o <= 1'b0;
          src1_rdy_o <= 1'b0;
        end
      endcase
    end
  end
  always @(posedge clk) begin
    if (clear) begin
      data0_o <= 36'h0;
      data1_o <= 36'h0;
    end else begin
      case (state)
        2'b00: begin
          data0_o <= 36'h0;
          data1_o <= 36'h0;
        end
        2'b01: begin
          data0_o <= data_i;
          data1_o <= 36'h0;
        end
        2'b10: begin
          data0_o <= 36'h0;
          data1_o <= data_i;
        end
        default: begin
          data0_o <= 36'h0;
          data1_o <= 36'h0;
        end
      endcase
    end
  end
endmodule

module branch_ctrl(
	input [31:0]	data_rs1	,
	input [31:0]	data_rs2	,
	input [2:0]		funct3		,
	output	reg		jmpb
);
always @(*) begin
		jmpb = 0;
		case (funct3)
			4'b000: begin
				if (data_rs1 == data_rs2)
					jmpb = 1;
			end
			4'b001: begin
				if (data_rs1 != data_rs2)
					jmpb = 1;
			end
			4'b100: begin
				if (data_rs1 < data_rs2)
					jmpb = 1;
			end
			4'b101: begin
				if (data_rs1 > data_rs2)
					jmpb = 1;
			end
			4'b110: begin
				if (data_rs1 < 0 && data_rs2 >= 0)
					jmpb = 1;
				else if (data_rs1 >= 0 && data_rs2 < 0)
					jmpb = 1;
			end
			4'b111: begin
				if (data_rs1 > 0 && data_rs2 <= 0)
					jmpb = 1;
				else if (data_rs1 <= 0 && data_rs2 > 0)
					jmpb = 1;
			end
		endcase
	end
endmodule

