module divider 
#(
    parameter WIDTH=23,
    parameter MODULO=6000000
)
(
    input input_clk,
    output output_clk
);
reg [WIDTH-1:0] counter;
    reg output_clk_reg;
    initial
    begin
        counter = 0;
        output_clk_reg = 0;
    end
    always @(posedge input_clk)
    begin
        if (counter == MODULO-1)
        begin
            counter = 0;
            output_clk_reg = ~output_clk_reg;
        end
        else
        begin
            counter = counter + 1;
        end
    end
    assign output_clk = output_clk_reg;
endmodule

