    if(rst) begin
      uni <= 4'b0000;
      dec <= 4'b0000;
    end
    else begin
      if(dig[9]) begin
        uni <= 4'b0001;
      end
      else if(dig[8]) begin
        uni <= 4'b0010;
      end
      else if(dig[7]) begin
        uni <= 4'b0100;
      end
      else if(dig[6]) begin
        uni <= 4'b1000;
      end
      else begin
        uni <= 4'b0000;
      end
    end
  end
endmodule

