module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [6:0] reg_data;
reg [2:0] reg_ctrl;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      reg_data <= 7'b0000000;
      reg_ctrl <= 3'b000;
    end else begin
      if((WR == 1'b1)) begin
        reg_data <= D;
        reg_ctrl <= A;
      end
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      Y <= 7'b0000000;
    end else begin
      if((RD == 1'b1)) begin
        Y <= reg_data;
      end
    end
  end
  assign WCTRL = reg_ctrl;
endmodule

