module parallel_if();
reg [3:0] counter;
    reg reset;
    reg enable;
    reg up_en;
    reg down_en;
    reg [1:0] dir;
    wire [1:0] dir;
    wire [3:0] counter;
    wire reset;
    wire enable;
    wire up_en;
    wire down_en;
    always @(posedge clock)
    begin
        if(reset)
            counter <= 4'b0000;
        else if(enable)
            if(dir == 2'b00)
                counter <= counter + 4'b0001;
            else
                counter <= counter - 4'b0001;
    end
endmodule

