module pingpongmem(clk, rst, wren, rden, address1, address2,
                    datain, dataout, inputsize);
input clk,rst;
input wren, rden;
input [31:0] inputsize;
input [31:0] address1, address2;

input [64*16-1:0] datain;
output reg [16*16-1:0] dataout;
reg [16*16-1:0] datainmem, dataoutmem;
reg [64*16-1:0] datamem [0:65535];

always @(posedge clk) begin
    if(rst) begin
        datainmem <= 0;
        dataoutmem <= 0;
        for (int i = 0; i < 65536; i = i + 1) begin
            datamem[i] <= 0;
        end
    end
    else if(wren) begin
        if(address1 == 0) begin
            datamem[address2] <= datain;
        end
        else if(address1 == 1) begin
            datamem[address2 + inputsize] <= datain;
        end
    end
    else if(rden) begin
        if(address1 == 0) begin
            dataoutmem <= datamem[address2];
        end
        else if(address1 == 1) begin
            dataoutmem <= datamem[address2 + inputsize];
        end
    end
end

assign dataout = dataoutmem;
endmodule

module hardcopyiii_ddr_gray_decoder (
        gin, 
        bout
);

input  [width-1 : 0] gin;
output [width-1 : 0] bout;
parameter width = 1;

