module dhcp_client_m_axis_open_port_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
parameter DEPTH = 2**DEPTH_BITS - 1;

reg [DATA_BITS-1:0] mem [0:DEPTH];
reg [31:0]          index;
reg                 empty;
reg                 full;

assign empty_n = ~empty;
assign full_n  = ~full;

always @(posedge clk) begin
    if (aclr) begin
        empty <= 1'b1;
        full  <= 1'b0;
        index <= 0;
    end else begin
        if (write) begin
            mem[index] <= din;
            index <= index + 1;
            if (index == DEPTH) begin
                full <= 1'b1;
                empty <= 1'b0;
            end
        end
        if (read) begin
            if (index == 0) begin
                empty <= 1'b1;
                full  <= 1'b0;
            end
            index <= index - 1;
            if (index == 0) begin
                empty <= 1'b0;
                full  <= 1'b1;
            end
            dout <= mem[index];
        end
    end
end

endmodule

