module pwm(
input wire clk,
input wire rst,
input wire [31:0] duty,
output reg pwm_out
); 

parameter [31:0] PERIOD=8;
reg [31:0] duty_reg;
reg [31:0] counter;
  always @(posedge clk) begin
    if(rst == 1'b1) begin
      counter <= 0;
      pwm_out <= 1'b0;
      duty_reg <= duty;
    end else begin
      if(counter < duty_reg) begin
        pwm_out <= 1'b1;
      end else begin
        pwm_out <= 1'b0;
      end
      if(counter == (PERIOD - 1)) begin
        counter <= 0;
        duty_reg <= duty;
      end else begin
        counter <= counter + 1;
      end
    end
  end
endmodule

module KeyEncoder(Columns, Rows, Clock, Reset, OnesDigit, TensDigit, Found);
	input [3:0] Columns;
	input [3:0] Rows;
	input Clock, Reset;
	output reg [3:0] OnesDigit;
	output reg [3:0] TensDigit;
	output reg Found;
parameter [8:0] KeyMap [0:15] = 
		{
			{4'b0000, 4'b0000, 4'b0000, 4'b0000}, 
			{4'b0001, 4'b0001, 4'b0001, 4'b0001}, 
			{4'b0010, 4'b0010, 4'b0010, 4'b0010}, 
			{4'b0011, 4'b0011, 4'b0011, 4'b0011}, 
			{4'b0100, 4'b0100, 4'b0100, 4'b0100}, 
			{4'b0101, 4'b0101, 4'b0101, 4'b0101}, 
			{4'b0110, 4'b0110, 4'b0110, 4'b0110}, 
			{4'b0111, 4'b0111, 4'b0111, 4'b0111}, 
			{4'b1000, 4'b1000, 4'b1000, 4'b1000}, 
			{4'b1001, 4'b1001, 4'b1001, 4'b1001}, 
			{4'b1010, 4'b1010, 4'b1010, 4'b1010}, 
			{4'b1011, 4'b1011, 4'b1011, 4'b1011}, 
			{4'b1100, 4'b1100, 4'b1100, 4'b1100}, 
			{4'b1101, 4'b1101, 4'b1101, 4'b1101}, 
			{4'b1110, 4'b1110, 4'b1110, 4'b1110}
		};
	always @(posedge Clock) begin
		if (Reset) begin
			Found <= 1'b0;
			OneDigit <= 4'b0000;
			TensDigit <= 4'b0000;
		end
		else begin
			if (KeyMap[Columns[0] + 4*Rows[0] + 4*Rows[1] + 4*Rows[2] + 4*Rows[3]] == 9'b111111111) begin
				Found <= 1'b1;
				OneDigit <= KeyMap[Columns[0] + 4*Rows[0] + 4*Rows[1] + 4*Rows[2] + 4*Rows[3]][4:1];
				TensDigit <= KeyMap[Columns[0] + 4*Rows[0] + 4*Rows[1] + 4*Rows[2] + 4*Rows[3]][3:0];
			end
			else begin
				Found <= 1'b0;
				OneDigit <= 4'b0000;
				TensDigit <= 4'b0000;
			end
		end
	end
endmodule

