module uds_counter(up, down, set, in, out, clk);
	input [WIDTH-1:0] in;
	input up, down, set, clk;
	output reg [WIDTH-1:0] out;
parameter WIDTH = 8;
	localparam MAX = 2**WIDTH-1;
	wire [2:0] uds;

	always @(posedge clk)
	begin
		if (up)
			out <= in;
		else if (set)
		begin
			if (out < MAX)
				out <= out + 1;
			else
				out <= 0;
		end
		else if (down)
		begin
			if (out > 0)
				out <= out - 1;
			else
				out <= MAX;
		end
		else
			out <= out;
	end

	initial
	begin
		out <= 0;
	end

endmodule

