module sparc_ifu_sscan(
    input wire [10:0] swl_sscan_thrstate,
    input wire [3:0] ifq_sscan_test_data,
    input wire [15:0] lsu_sscan_test_data,
    input wire [62:0] tlu_sscan_test_data,
    input wire rclk,


    output reg [94-1:0] core_rtap_data,
    input wire rtap_core_val,
    input wire [1:0] rtap_core_threadid,
    input wire [4-1:0]  rtap_core_id,
    input wire [94-1:0] rtap_core_data

    );
reg [94-1:0] snap_data;
    reg [94-1:0] snap_data_next;
    reg [1:0] rtap_sscan_snap;
    reg [1:0] rtap_sscan_snap_f;

    always @(posedge rclk) begin
        snap_data <= snap_data_next;
    end

    always @(posedge rclk) begin
        if (rtap_core_val && rtap_core_id == 5) begin
            snap_data_next <= {ifq_sscan_test_data, lsu_sscan_test_data, tlu_sscan_test_data, swl_sscan_thrstate};
        end
    end

    always @(posedge rclk) begin
        if (rtap_core_val && rtap_core_id == 5) begin
            rtap_sscan_snap <= 2'b01;
            rtap_sscan_snap_f <= 2'b01;
        end
        else if (rtap_sscan_snap == 2'b10) begin
            rtap_sscan_snap <= 2'b00;
            rtap_sscan_snap_f <= 2'b00;
        end
    end

    always @(posedge rclk) begin
        if (rtap_sscan_snap_f == 2'b01) begin
            core_rtap_data <= snap_data;
        end
    end

endmodule

