module Control(
   
	input wire clk,rst,
	input [7:0] in3,in2,in1,in0,
	output reg [3:0] anodo,
	output reg [7:0] catodo
    );
localparam N=18;
reg [N-1:0] q_reg;
always @(posedge clk or posedge rst)
begin
	if(rst)
		q_reg<=0;
	else
		q_reg<=q_reg+1;
end
always @(posedge clk)
begin
	case(q_reg[15:14])
		2'b00:anodo<=in0;
		2'b01:anodo<=in1;
		2'b10:anodo<=in2;
		2'b11:anodo<=in3;
	endcase
	catodo<=q_reg[13:6];
end
endmodule

