module table_010101010(input clk, input rst, input [14:0] addr, output reg match);
always @(posedge clk) begin
    casex (addr)
      15'b000000000000000: match <= 1'b1;
      15'b000000000000001: match <= 1'b1;
      default: match <= 1'b0;
    endcase
    if (rst) match <= 1'b0;
  end
endmodule

