module PC(PC_out,PC_in,load,inc,clk,rst);

output	[7:0]PC_out;
input	[7:0]PC_in;
input	load,inc,clk,rst;
reg	[7:0]PC_out;
reg	[7:0]PC_in;
reg	load,inc,clk,rst;
always@(posedge clk)
begin
	if(rst)
		PC_out<=0;
	else if(load)
		PC_out<=PC_in;
	else if(inc)
		PC_out<=PC_out+1;
end
endmodule

