module mash(
input wire [63:0] din,
output wire [31:0] dout
); 

wire [31:0] even_bits;
wire [31:0] odd_bits;
  assign dout = |even_bits | odd_bits;
  generate
    for (genvar i = 0; i < 32; i = i + 1) begin : gen
      assign even_bits[i] = din[2 * i];
      assign odd_bits[i] = din[2 * i + 1];
    end
  endgenerate
endmodule

module mylfsr2(
input wire [7:0] starting,
output wire [7:0] lfsr2_out,
input wire clk,
input wire rst,
input wire en
); 

reg [7:0] lfsr2;
  assign lfsr2_out = lfsr2;
  always @(posedge clk) begin
    if((rst == 1'b0)) begin
      lfsr2 <= starting;
    end
    else if((en == 1'b1)) begin
      lfsr2 <= {lfsr2[6:0], lfsr2[7]};
    end
  end
endmodule

