module first_counter (
clock , 
reset , 
enable , 
counter_out 
); 

input clock ;
input reset ;
input enable ;

output [3:0] counter_out ;
reg [3:0] counter_out ;

always @(posedge clock) begin
    if (reset == 1'b1) begin
