module ram(
  input clk,
  input enable,
  input write_enable,
  input [WIDTH-1 : 0] addr,
  input [WIDTH-1 : 0] data_in,
  output [WIDTH-1 : 0] data_out);
parameter ADDRESS_WIDTH = 16;
  parameter WIDTH = 8;
  parameter MEMORY_SIZE = 1 << ADDRESS_WIDTH;

  reg [WIDTH-1 : 0] mem[MEMORY_SIZE-1 : 0];
  initial begin
    $readmemh("prog_fib.list", mem);
  end

  always @(posedge clk) begin
    if (write_enable) begin
      mem[addr] <= data_in;
    end
  end

  assign data_out = enable ? mem[addr] : 0;
endmodule

