module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg  updateclk;
reg  capture;
reg  update;
reg  mainclk;

always @ (captnupdt or shiftnld or clk) begin
    case ({captnupdt, shiftnld})
        2'b10, 2'b11: begin
            updateclk <= clk;
            capture  <= 1'b1;
        end
        2'b01: begin
            updateclk <= clk;
            capture  <= 1'b0;
        end
        default: begin
            mainclk <= clk;
            update  <= 1'b1;
        end
    endcase
end

initial begin
    updateclk <= 1'b0;
    capture  <= 1'b0;
    update  <= 1'b0;
    mainclk <= 1'b0;
end

endmodule

module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);
reg [15:0] V_cnt;
reg [15:0] H_cnt;
reg Pout_de_w;
reg Pout_hs_w;
reg Pout_vs_w;
reg Rden_w;
always @(posedge I_pxl_clk or negedge I_rst_n)
begin
    if (~I_rst_n)
    begin
        V_cnt <= 16'd0;
        H_cnt <= 16'd0;
    end
    else
    begin
        V_cnt <= V_cnt + 16'd1;
        H_cnt <= H_cnt + 16'd1;
    end
end
always @(posedge I_pxl_clk or negedge I_rst_n)
begin
    if (~I_rst_n)
    begin
        Pout_de_w <= 1'b0;
        Pout_hs_w <= 1'b0;
        Pout_vs_w <= 1'b0;
        Rden_w <= 1'b0;
    end
    else
    begin
        if (V_cnt == I_v_total)
        begin
            Pout_de_w <= 1'b1;
            Pout_hs_w <= 1'b1;
            Pout_vs_w <= 1'b1;
            Rden_w <= 1'b1;
        end
        else
        begin
            Pout_de_w <= 1'b0;
            Pout_hs_w <= 1'b0;
            Pout_vs_w <= 1'b0;
            Rden_w <= 1'b0;
        end
    end
end
always @(posedge I_pxl_clk or negedge I_rst_n)
begin
    if (~I_rst_n)
    begin
        O_de <= 1'b0;
        O_hs <= 1'b0;
        O_vs <= 1'b0;
    end
    else
    begin
        if (Pout_de_w)
        begin
            O_de <= 1'b1;
        end
        else
        begin
            O_de <= 1'b0;
        end
        if (Pout_hs_w)
        begin
            O_hs <= I_hs_pol;
        end
        else
        begin
            O_hs <= 1'b0;
        end
        if (Pout_vs_w)
        begin
            O_vs <= I_vs_pol;
        end
        else
        begin
            O_vs <= 1'b0;
        end
    end
end
always @(posedge I_pxl_clk or negedge I_rst_n)
begin
    if (~I_rst_n)
    begin
        O_rden <= 1'b0;
    end
    else
    begin
        if (Rden_w)
        begin
            O_rden <= 1'b1;
        end
        else
        begin
            O_rden <= 1'b0;
        end
    end
end
endmodule

module alu
    #(parameter WIDTH = 32)
    (   input  [WIDTH - 1 : 0] a,b,
        input  [2 : 0] m,
        output reg [WIDTH - 1 : 0] y,
        output reg zf,      
        output reg cf,      
        output reg of      
    );
always @* begin
        case (m)
            3'b000: y = a + b;
            3'b001: y = a - b;
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = a + b;
            3'b110: y = a - b;
            3'b111: y = a & b;
        endcase
        zf = (y == 0);
        cf = (y == 0);
        of = (a[WIDTH - 1] ^ b[WIDTH - 1] ^ y[WIDTH - 1]) & (a[WIDTH - 2] ^ b[WIDTH - 2] ^ y[WIDTH - 2]) & cf;
    end
endmodule

