module DFF_en2(clk ,nRST, en, D, Q);
input wire [n-1:0] D;
input wire en;
input wire clk;
input wire nRST;
output reg [n-1:0] Q;
parameter n = 32;
always @(posedge clk, posedge nRST) begin
    if(nRST == 1'b0) begin
