    end
end
endmodule

module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
parameter DEPTH = 1 << DEPTH_BITS;
    reg [DATA_BITS-1:0] mem [0:DEPTH-1];
    reg [DATA_BITS-1:0] index;
    reg empty_n;
    reg full_n;
    wire [DATA_BITS-1:0] dout;
    assign dout = mem[index];
    always @(posedge clk) begin
        if (aclr) begin
            empty_n <= 1'b1;
            full_n  <= 1'b0;
            index   <= 0;
        end else begin
            if (write) begin
                if (full_n) begin
                    empty_n <= 1'b1;
                    full_n  <= 1'b0;
                end
                mem[index] <= din;
                index <= index + 1;
            end
            if (read) begin
                if (empty_n) begin
                    empty_n <= 1'b0;
                    full_n  <= 1'b1;
                end
                index <= index - 1;
            end
        end
    end
endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
); 

reg [31:0] timer;
reg pre;
  always @(posedge clk) begin
    if(timer == 1000000) begin
      if(btn_input == pre) begin
        timer <= 0;
        btn_output <= btn_input;
      end
      else begin
        timer <= 0;
      end
    end
    else begin
      timer <= timer + 1;
    end
    pre <= btn_input;
  end
endmodule

