module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
localparam                 IDLE = 2'b00;
  localparam                 READY = 2'b01;
  localparam                 RELEASE = 2'b10;

  reg [31:0]                 r_count;
  reg [1:0]                 state;
  reg [2:0]                 r_ppfifo_size;

  always @(posedge clk) begin
    if (rst) begin
      r_count <= 0;
      state <= IDLE;
      r_ppfifo_size <= 0;
    end else begin
      case (state)
        IDLE: begin
          if (i_h_blank == 0) begin
            r_count <= 0;
            state <= READY;
          end
        end
        READY: begin
          if (i_h_blank == 0) begin
            r_count <= r_count + 1;
            if (r_count == i_ppfifo_size) begin
              state <= RELEASE;
            end
          end
        end
        RELEASE: begin
          if (i_h_blank == 0) begin
            r_count <= 0;
            state <= IDLE;
          end
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      o_ppfifo_clk <= 0;
      o_ppfifo_act <= 0;
      o_ppfifo_stb <= 0;
      o_ppfifo_data <= 0;
    end else begin
      case (state)
        IDLE: begin
          o_ppfifo_clk <= clk;
          o_ppfifo_act <= 0;
          o_ppfifo_stb <= 0;
          o_ppfifo_data <= 0;
        end
        READY: begin
          o_ppfifo_clk <= clk;
          o_ppfifo_act <= i_ppfifo_rdy;
          o_ppfifo_stb <= i_data_en;
          o_ppfifo_data <= i_rgb;
        end
        RELEASE: begin
          o_ppfifo_clk <= clk;
          o_ppfifo_act <= 0;
          o_ppfifo_stb <= 0;
          o_ppfifo_data <= 0;
        end
      endcase
    end
  end

endmodule

