module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );



	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
reg	[6:0]	data_reg;
	reg	[6:0]	data_regnum;
	reg	data_out_sign;
	reg	data_ok;

	always @(posedge clk or negedge rst_n) begin
		if (~rst_n) begin
			data_reg <= 0;
			data_regnum <= 0;
			data_out_sign <= 0;
			data_ok <= 0;
		end else begin
			if (data_in_sign) begin
				data_reg <= data_reg + data_in;
				data_regnum <= data_regnum + 1;
			end
			if (data_valid) begin
				data_out_sign <= 1;
				data_out <= data_reg;
			end
			if (data_regnum == 8) begin
				if (data_reg == 28 || data_reg == 36) begin
					data_ok <= 1;
				end
			end
		end
	end
endmodule

module clk_div(
input wire clk_100MHz,
input wire reset,
output wire clk_100Hz
); 

reg [31:0] ticks;
  wire clk_out;
  assign clk_out = ~clk_out;
  always @(posedge clk_100MHz, posedge reset) begin
    if(reset == 1'b1) begin
      ticks <= 499999;
      clk_100Hz <= 0;
    end else begin
      if(ticks == 0) begin
        clk_100Hz <= ~clk_out;
        ticks <= 499999;
      end else begin
        ticks <= ticks - 1;
      end
    end
  end
endmodule

