always @(posedge clkin)
begin
if(en)
begin
pc=pc+1;
end
end
always @(negedge clkin)
begin
if(en)
begin
nc=nc+1;
end
end
always @(posedge clkin or negedge en)
begin
if(en)
begin
if(pc==n/2)
begin
clkout=1;
end
else
begin
clkout=0;
end
end
end
always @(negedge clkin or negedge en)
begin
if(en)
begin
if(nc==n/2+1)
begin
clkout=1;
end
else
begin
clkout=0;
end
end
end
endmodule

