module DelayLoop(MR,Timeout,Clock) ;
input			MR, Clock;
output reg	Timeout;
parameter Divider=100000;
reg [26:0] Counter;
always @(posedge Clock)
begin
	if(MR)
		Counter <= 0;
	else if(Counter == Divider)
		Counter <= 0;
	else
		Counter <= Counter + 1;
end
always @(Counter)
begin
	if(Counter == Divider)
		Timeout <= 1;
	else
		Timeout <= 0;
end
endmodule

