module toe_m_axis_rx_data_rsp_metadata_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0] ZERO = 2'b00;
    localparam [1:0] ONE = 2'b01;
    localparam [1:0] TWO = 2'b10;

    reg [N-1:0] data_p1;
    reg [N-1:0] data_p2;
    reg load_p1;
    reg load_p2;
    reg load_p1_from_p2;
    reg [1:0] state;

    always @(posedge clk) begin
        if (reset) begin
            state <= ZERO;
            load_p1 <= 1'b0;
            load_p2 <= 1'b0;
            load_p1_from_p2 <= 1'b0;
        end else begin
            case (state)
                ZERO: begin
                    if (s_valid && s_ready) begin
                        state <= ONE;
                        load_p1 <= 1'b1;
                        load_p2 <= 1'b0;
                    end
                end
                ONE: begin
                    if (s_valid && s_ready) begin
                        state <= TWO;
                        load_p1 <= 1'b1;
                        load_p2 <= 1'b0;
                    end
                    else if (m_ready) begin
                        state <= ZERO;
                        load_p1 <= 1'b0;
                        load_p2 <= 1'b0;
                    end
                end
                TWO: begin
                    if (s_valid && s_ready) begin
                        state <= ZERO;
                        load_p1 <= 1'b1;
                        load_p2 <= 1'b0;
                    end
                    else if (m_ready) begin
                        state <= ZERO;
                        load_p1 <= 1'b0;
                        load_p2 <= 1'b0;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            data_p1 <= 0;
            data_p2 <= 0;
        end else begin
            if (load_p1) begin
                data_p1 <= s_data;
            end
            if (load_p2) begin
                data_p2 <= s_data;
            end
            if (load_p1_from_p2) begin
                data_p1 <= data_p2;
            end
        end
    end

    assign m_data = data_p1;
    assign m_valid = load_p1;
    assign s_ready = m_ready;

    always @(posedge clk) begin
        if (reset) begin
            load_p1 <= 1'b0;
            load_p2 <= 1'b0;
            load_p1_from_p2 <= 1'b0;
        end else begin
            if (s_valid && s_ready) begin
                load_p1 <= 1'b0;
                load_p2 <= 1'b0;
                load_p1_from_p2 <= 1'b0;
            end
            else if (m_ready) begin
                load_p1 <= 1'b1;
                load_p2 <= 1'b0;
                load_p1_from_p2 <= 1'b0;
            end
            else if (m_valid) begin
                load_p1 <= 1'b0;
                load_p2 <= 1'b1;
                load_p1_from_p2 <= 1'b0;
            end
            else if (m_ready && m_valid) begin
                load_p1 <= 1'b0;
                load_p2 <= 1'b0;
                load_p1_from_p2 <= 1'b1;
            end
        end
    end

endmodule

