module udpAppMux_txLengthNetwork_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
parameter DEPTH = 1 << DEPTH_BITS;

reg [DATA_BITS-1:0] mem [0:DEPTH-1];
reg [DATA_BITS-1:0] index;
reg [DATA_BITS-1:0] empty_n_reg;
reg [DATA_BITS-1:0] full_n_reg;

assign empty_n = ~empty_n_reg;
assign full_n  = ~full_n_reg;
assign dout    = mem[index];

always @(posedge clk or posedge aclr) begin
    if (aclr) begin
        index <= 0;
        empty_n_reg <= 1;
        full_n_reg <= 0;
    end else begin
        if (write) begin
            mem[index] <= din;
            index <= index + 1;
            if (index == DEPTH - 1) begin
                full_n_reg <= 1;
            end
        end
        if (read) begin
            index <= index - 1;
            if (index == 0) begin
                empty_n_reg <= 1;
            end
        end
    end
end

generate
    genvar i;
    for (i = 0; i < DATA_BITS; i = i + 1) begin
        reg [DATA_BITS-1:0] shift_reg;
        always @(posedge clk) begin
            if (write) begin
                shift_reg <= mem[index];
            end
            if (read) begin
                mem[index] <= shift_reg;
            end
        end
        assign mem[index][i] = shift_reg[i];
    end
endgenerate

endmodule

module Counter_Controller #(
    parameter   DWIDTH = 7
)(
    input                   clk,
    input                   rst_n,
    input                   start_i,
    input   [DWIDTH-1:0]    cnt_val_i,
    input   [DWIDTH-1:0]    cnt_i,
    output                  run_o,
    output                  done_o
);
parameter   S_IDLE = 0;
    parameter   S_RUN = 1;
    parameter   S_DONE = 2;

    reg [1:0] state = S_IDLE;
    reg [DWIDTH-1:0] cnt_val = 0;
    reg [DWIDTH-1:0] cnt_val_n = 0;
    reg run = 0;
    reg done = 0;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            cnt_val <= 0;
            run <= 0;
            done <= 0;
        end else begin
            case (state)
                S_IDLE: begin
                    if (start_i) begin
                        state <= S_RUN;
                        cnt_val <= cnt_val_i;
                    end
                end
                S_RUN: begin
                    if (cnt_val == cnt_i) begin
                        state <= S_DONE;
                        run <= 0;
                        done <= 1;
                    end
                    else begin
                        run <= 1;
                    end
                end
                S_DONE: begin
                    state <= S_IDLE;
                    run <= 0;
                    done <= 0;
                end
            endcase
        end
    end

    assign run_o = run;
    assign done_o = done;

endmodule

