module Control(
		input clk,
		input start,
		output[3:0] direction,
		output ready
	);
reg[2:0] state;
	assign direction = {state[1],state[2],state[0]};
	assign ready = state[0] == 0 && state[1] == 0 && state[2] == 0;
	always @(posedge clk) begin
		if(start) begin
			state <= 3'b000;
		end
		else if(state[1] == 0 && state[2] == 0) begin
			state <= state + 3'b001;
		end
		else if(state[1] == 0 && state[2] == 1) begin
			state <= state + 3'b010;
		end
		else if(state[1] == 1 && state[2] == 0) begin
			state <= state + 3'b100;
		end
		else if(state[1] == 1 && state[2] == 1) begin
			state <= state + 3'b101;
		end
	end
endmodule

