module sparc_ifu_esl_lfsr
(
    input               clk,
    input               rst_n,


    input [15:0]        lfsr_seed,
    input               lfsr_ld,


    input               lfsr_step,


    output reg [15:0]   lfsr_state_f,


    output reg          lfsr_out_f
);
localparam LFSR_WIDTH = 16;
localparam LFSR_FEEDBACK_TAPS = 16'b00000000000000000000000000000001;

always @(posedge clk or negedge rst_n)
begin
    if (!rst_n)
    begin
        lfsr_state_f <= 16'b0;
    end
    else
    begin
        if (lfsr_ld)
        begin
            lfsr_state_f <= lfsr_seed;
        end
        else if (lfsr_step)
        begin
            lfsr_state_f <= {lfsr_state_f[LFSR_WIDTH-1:1], lfsr_state_f[0] ^ lfsr_state_f[LFSR_FEEDBACK_TAPS-1] ^ lfsr_state_f[LFSR_FEEDBACK_TAPS-2]};
        end
    end
end

assign lfsr_out_f = lfsr_state_f[LFSR_WIDTH-1];

endmodule

