module button_pulse 
#(
    parameter MAX_COUNT = 8,    
    parameter DEC_COUNT = 2,    
    parameter MIN_COUNT = 1     
)(
    input wire clk,
    input wire clk_en,
    input wire button,
    input wire reset,
    output wire pulse
);
reg [31:0] comp = MAX_COUNT - 1;
    reg [31:0] count = 0;
    wire button_pressed = button & ~reset;
    wire button_released = ~button & reset;
    always @(posedge clk) begin
        if (clk_en) begin
            if (button_pressed) begin
                if (count == 0) begin
                    comp <= comp - DEC_COUNT;
                    count <= count + 1;
                end
                else if (comp == MIN_COUNT) begin
                    comp <= MAX_COUNT - 1;
                    count <= 0;
                end
            end
            else if (button_released) begin
                comp <= MAX_COUNT - 1;
                count <= 0;
            end
        end
    end
    assign pulse = count == 0 & button_pressed;
endmodule

