reg load_p2;
reg load_p1_from_p2;
reg [1:0] state;
reg [1:0] next;

always @ (posedge clk or posedge reset) begin
    if (reset) begin
        data_p1 <= 0;
        data_p2 <= 0;
        load_p1 <= 0;
        load_p2 <= 0;
        load_p1_from_p2 <= 0;
        state <= 2'b00;
        next <= 2'b00;
    end else begin
        data_p1 <= data_p2;
        data_p2 <= s_data;
        load_p1 <= s_valid & m_ready;
        load_p2 <= load_p1_from_p2;
        load_p1_from_p2 <= load_p1;
        state <= next;
    end
