    if (reset) begin
        m_data <= 0;
    end else begin
        m_data <= state == 2'b01 ? data_p1 : data_p2;
    end
end

always @ (posedge clk or posedge reset) begin
    if (reset) begin
        state <= 2'b00;
    end else begin
        state <= next;
    end
end

always @ (posedge clk or posedge reset) begin
    if (reset) begin
        load_p1 <= 0;
    end else begin
        load_p1 <= load_p1_from_p2;
    end
end

always @ (posedge clk or posedge reset) begin
    if (reset) begin
        load_p2 <= 0;
    end else begin
        load_p2 <= load_p1;
    end
