module Data_CrossDomain(
    input clkA,
    input FlagIn_clkA, 
    input clkB,
    output FlagOut_clkB,
	input [7:0] dataA,
	output [7:0] dataB
);
reg [2:0] SyncA_clkB;
    reg clkA_data;
    reg clkB_data;
    reg FlagToggle_clkA;
    always @(posedge clkA) begin
        FlagToggle_clkA <= FlagIn_clkA;
    end
    always @(posedge clkA) begin
        if (FlagToggle_clkA == 1'b1) begin
            clkA_data <= dataA;
        end
    end
    always @(posedge clkB) begin
        if (FlagToggle_clkA == 1'b1) begin
            clkB_data <= clkA_data;
        end
    end
    always @(posedge clkB) begin
        if (FlagToggle_clkA == 1'b1) begin
            SyncA_clkB <= clkB_data;
        end
    end
    always @(posedge clkB) begin
        if (FlagToggle_clkA == 1'b1) begin
            FlagOut_clkB <= SyncA_clkB[2];
        end
    end
endmodule

