module pe(
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] c
);
wire [63:0] product;
    assign product = a * b;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            c <= 0;
        end else begin
            c <= c + product[31:0];
        end
    end
endmodule

module testbench;
reg [2:0] A, B;
wire A_greater, A_equal, A_less;

comparator_3bit comp(A, B, A_greater, A_equal, A_less);

initial begin
    $display("Starting testbench");
    for (i = 0; i < 100; i = i + 1) begin
        A = $random;
        B = $random;
        if (A > B) begin
            if (!A_greater) begin
                $display("Test %d failed: A > B, but A_greater is not set", i);
                error = error + 1;
            end
        end
        else if (A < B) begin
            if (!A_less) begin
                $display("Test %d failed: A < B, but A_less is not set", i);
                error = error + 1;
            end
        end
        else begin
            if (!A_equal) begin
                $display("Test %d failed: A = B, but A_equal is not set", i);
                error = error + 1;
            end
        end
    end
    if (error == 0) begin
        $display("Testbench passed");
    end
    else begin
        $display("Testbench failed %d times", error);
    end
end

endmodule

module muland_2_stage_signed_9_bit(
	input signed [8:0] a,
	input signed [8:0] b,
	input signed [8:0] c,
	output [8:0] out,
	input clk);
logic signed [17:0] stage0;
	logic signed [17:0] stage1;

	always @(posedge clk) begin
	stage0 <= (a * b) & c;
	stage1 <= stage0;
	end

	assign out = stage1;
endmodule

