module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );
localparam SEED = 32'h00000000;
  reg [31:0] M_x, M_y, M_z, M_w, M_w_d;
  reg [31:0] M_x_q, M_y_q, M_z_q, M_w_q;
  reg [31:0] t;
  always @(posedge clk) begin
    if (rst) begin
      M_x <= SEED;
      M_y <= seed;
      M_z <= SEED;
      M_w <= SEED;
    end else begin
      M_x_q <= M_x;
      M_y_q <= M_y;
      M_z_q <= M_z;
      M_w_q <= M_w;
      M_x <= M_x_q;
      M_y <= M_y_q;
      M_z <= M_z_q;
      M_w <= M_w_q;
    end
  end
  always @(M_x, M_y, M_z, M_w) begin
    t = M_x_q ^ M_y_q;
    M_w_d = M_z_q ^ t;
  end
  always @(posedge clk) begin
    if (next) begin
      M_w <= M_w_d;
    end
  end
endmodule

