module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;
reg [2:0] state;
assign red = (state == 3'b000) ? 1'b1 : 1'b0;
assign yellow = (state == 3'b001) ? 1'b1 : 1'b0;
assign green = (state == 3'b010) ? 1'b1 : 1'b0;
initial begin
	state = 3'b000;
end
always @(posedge clk or posedge reset) begin
	if(reset == 1'b1) begin
		state <= 3'b000;
	end
	else begin
		case(state)
			3'b000: state <= 3'b001;
			3'b001: state <= 3'b010;
			3'b010: state <= 3'b000;
			default: state <= 3'b000;
		endcase
	end
end
endmodule

