    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
parameter NUM_DIV = 6;
    reg [31:0] cnt;
    reg clk_div;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            cnt <= 0;
            clk_div <= 0;
        end else begin
            if(cnt == (NUM_DIV/2)) begin
                clk_div <= ~clk_div;
                cnt <= 0;
            end else begin
                cnt <= cnt + 1;
            end
        end
    end
endmodule

