module mux12#(parameter DATA_SIZE = 8)
       (input [7:0][DATA_SIZE-1:0] in0_7,
        input [DATA_SIZE-1:0] in8,
        input [DATA_SIZE-1:0] in9,
        input [DATA_SIZE-1:0] in10,
        input [DATA_SIZE-1:0] in11, 
        input [3:0] sel, output [DATA_SIZE-1:0] out);
wire [DATA_SIZE-1:0] out;
    assign out = sel[3] ? in11 : in10;
    assign out = sel[3] ? in9 : in8;
    assign out = sel[3] ? in7 : in0_7[sel[2:0]];
    assign out = sel[3] ? in6 : in0_7[sel[2:0]];
    assign out = sel[3] ? in5 : in0_7[sel[2:0]];
    assign out = sel[3] ? in4 : in0_7[sel[2:0]];
    assign out = sel[3] ? in3 : in0_7[sel[2:0]];
    assign out = sel[3] ? in2 : in0_7[sel[2:0]];
    assign out = sel[3] ? in1 : in0_7[sel[2:0]];
    assign out = sel[3] ? in0 : in0_7[sel[2:0]];
    always @* begin
        out = sel[3] ? in11 : in10;
        out = sel[3] ? in9 : in8;
        out = sel[3] ? in7 : in0_7[sel[2:0]];
        out = sel[3] ? in6 : in0_7[sel[2:0]];
        out = sel[3] ? in5 : in0_7[sel[2:0]];
        out = sel[3] ? in4 : in0_7[sel[2:0]];
        out = sel[3] ? in3 : in0_7[sel[2:0]];
        out = sel[3] ? in2 : in0_7[sel[2:0]];
        out = sel[3] ? in1 : in0_7[sel[2:0]];
        out = sel[3] ? in0 : in0_7[sel[2:0]];
    end
