  reg [1:0] memwr_s;
  reg [1:0] memrw_s;
  reg [1:0] opfetch_s;
  always @(posedge clk) begin
    if (!rst_n) begin
      iorq <= 2'b00;
      mreq <= 2'b00;
      iord <= 2'b00;
      iowr <= 2'b00;
      iordwr <= 2'b00;
      memrd <= 2'b00;
      memwr <= 2'b00;
      memrw <= 2'b00;
      opfetch <= 2'b00;
      intack <= 2'b00;
