module mux_256x1 (in,sel,out);
input [255:0] in;
input [7:0]sel;
output out;
wire [127:0]mux1;
wire [127:0]mux2;
wire [127:0]mux3;
assign mux1[127:0] = in[127:0];
assign mux2[127:0] = in[255:128];
assign mux3[127:0] = sel[7:0] ? mux1 : mux2;
assign out = sel[8] ? mux3[127:0] : in[255:128];
endmodule

module FIFO_arp_server_arpTableInsertFifo_V_shiftReg (
    clk,
    data,
    ce,
    a,
    q);

input clk;
input [DATA_WIDTH-1:0] data;
input ce;
input [ADDR_WIDTH-1:0] a;
output [DATA_WIDTH-1:0] q;
parameter DATA_WIDTH = 81;
parameter ADDR_WIDTH = 3;
parameter DEPTH = 5;

reg [DATA_WIDTH-1:0] SRL_SIG [0:DEPTH-1];

integer i;

always @(posedge clk) begin
    if (ce) begin
        for (i = DEPTH-1; i > 0; i = i - 1) begin
            SRL_SIG[i] <= SRL_SIG[i-1];
        end
        SRL_SIG[0] <= data;
    end
end

assign q = SRL_SIG[a];

endmodule

