module PulseCounter(
input wire clk,
output wire pulse
); 

parameter [31:0] upperBound = 28'd1000000000;
reg [27:0] count;
  always @(posedge clk) begin
    if(count == upperBound) begin
      count <= 0;
      pulse <= 1;
    end
    else begin
      count <= count + 1;
      pulse <= 0;
    end
  end
endmodule

