module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);
input clk; 
	input startGameEn; 
	input [7:0]user_x; 
	input [6:0]user_y; 
	input [7:0]enemy_x; 
	input [6:0]enemy_y; 
	input [160*120-1:0] enem_grid; 
	output reg [7:0] x; 
	output reg [6:0] y; 
	output reg[2:0] colour;
reg clear; 
	reg [7:0] x_next; 
	reg [6:0] y_next; 
	reg [2:0] colour_next; 
	always @(posedge clk) begin
		if(startGameEn) begin
			x <= 0;
			y <= 0;
			clear <= 1;
		end
		else begin
			if(x == 160 && y == 120) begin
				x <= 0;
				y <= 0;
			end
			else begin
				if(x == user_x && y == user_y) begin
					colour <= 3'b001;
				end
				else if(x == enemy_x && y == enemy_y) begin
					colour <= 3'b010;
				end
				else if(enem_grid[y*160 + x] == 1'b1) begin
					colour <= 3'b011;
				end
				else begin
					colour <= 3'b000;
				end
				x <= x + 1;
				y <= y + 1;
			end
		end
	end
endmodule

module Start_UP_Handler(
input wire i_CLK,
output wire o_RST
); 

parameter [31:0] g_Clock_Frequency = 100000000;
parameter [31:0] g_Initial_Reset_Time = 10000000;
reg r_RST;
reg r_RST_Counter;
wire c_Initial_Reset_Clocks;
  assign c_Initial_Reset_Clocks = g_Clock_Frequency * g_Initial_Reset_Time;
  always @(posedge i_CLK) begin
    if((r_RST_Counter == c_Initial_Reset_Clocks)) begin
      r_RST <= 1'b0;
    end
    else begin
      r_RST <= 1'b1;
    end
    r_RST_Counter <= r_RST_Counter + 1;
  end
  assign o_RST = r_RST;
endmodule

