module file_writer(input_a,input_a_stb,clk,rst,input_a_ack);

  input     clk;
  input     rst;

  input     [63:0] input_a;
  input     input_a_stb;
  output    input_a_ack;
reg [63:0] value;
  reg [1:0] state;
  reg s_input_a_ack;

  always @(posedge clk) begin
    if (rst) begin
      state <= 2'b00;
      s_input_a_ack <= 1'b0;
    end
    else begin
      case (state)
        2'b00: begin
          if (input_a_stb) begin
            value <= input_a;
            state <= 2'b01;
          end
        end
        2'b01: begin
          if (s_input_a_ack) begin
            state <= 2'b00;
          end
        end
        default: begin
          state <= 2'b00;
        end
      endcase
    end
  end

  always @(posedge clk) begin
    if (rst) begin
      s_input_a_ack <= 1'b0;
    end
    else begin
      if (input_a_stb) begin
        s_input_a_ack <= 1'b1;
      end
      else begin
        s_input_a_ack <= 1'b0;
      end
    end
  end

  initial begin
    $fopena("resp_z", "a");
  end

  always @(posedge clk) begin
    if (rst) begin
      $fdisplay("resp_z", "%d", value[63:32]);
      $fdisplay("resp_z", "%d", value[31:0]);
    end
    else begin
      if (s_input_a_ack) begin
        $fdisplay("resp_z", "%d", value[63:32]);
        $fdisplay("resp_z", "%d", value[31:0]);
      end
    end
  end

endmodule

