module top(
input wire clk,
input wire [2:0] sel_i,
input wire [7:0] data_in_i,
input wire write_i,
output wire [10:0] data_out_o
); 

reg [7:0] A;
  reg [7:0] B;
  reg [7:0] C;
  reg [7:0] D;
  reg [7:0] E;
  reg [7:0] F;
  reg [7:0] G;
  reg [7:0] H;
  wire [7:0] sum;
  assign data_out_o = sum;
  assign sum = {A,B,C,D,E,F,G,H};
  always @(posedge clk) begin
    if(write_i == 1'b1) begin
      case(sel_i)
        3'b000: A <= data_in_i;
        3'b001: B <= data_in_i;
        3'b010: C <= data_in_i;
        3'b011: D <= data_in_i;
        3'b100: E <= data_in_i;
        3'b101: F <= data_in_i;
        3'b110: G <= data_in_i;
        3'b111: H <= data_in_i;
      endcase
    end
  end
endmodule

