module BaudTickGen(
	input clk, enable,
	output tick  
);
parameter ClkFrequency = 100000000;
	parameter Baud = 115200;
	parameter Oversampling = 16;

	logic [31:0] Acc;
	logic [31:0] Inc;

	assign Inc = Baud * Oversampling;
	assign tick = Acc >= Inc;

	always @(posedge clk) begin
		if (enable) begin
			Acc <= Acc + 1;
		end
		else begin
			Acc <= 0;
		end
	end
endmodule

