module submuladd_2_stage_unsigned_8_bit(
	input  [7:0] a,
	input  [7:0] b,
	input  [7:0] c,
	input  [7:0] d,
	output [7:0] out,
	input clk);
logic  [15:0] stage0;
	logic  [15:0] stage1;

	always @(posedge clk) begin
	stage0 <= (d - a) * b + c;
	stage1 <= stage0;
	end

	assign out = stage1;
endmodule

module vga_sync_pulse
(
    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
);
parameter [9:0] TOTAL_COLUMNS = 1920;
    parameter [9:0] TOTAL_ROWS = 1080;
    parameter [9:0] ACTIVE_COLUMNS = 1280;
    parameter [9:0] ACTIVE_ROWS = 960;

    always @(posedge i_clk) begin
        if (o_col_count == TOTAL_COLUMNS) begin
            o_col_count <= 0;
        end else begin
            o_col_count <= o_col_count + 1;
        end
    end

    always @(posedge i_clk) begin
        if (o_row_count == TOTAL_ROWS) begin
            o_row_count <= 0;
        end else begin
            o_row_count <= o_row_count + 1;
        end
    end

    always @(posedge i_clk) begin
        if (o_col_count == ACTIVE_COLUMNS) begin
            o_hsync <= 1'b0;
        end else begin
            o_hsync <= 1'b1;
        end
    end

    always @(posedge i_clk) begin
        if (o_row_count == ACTIVE_ROWS) begin
            o_vsync <= 1'b0;
        end else begin
            o_vsync <= 1'b1;
        end
    end

endmodule

