module motor_rpm_count(
	input clk,
	input motor_rot_pulse,
	output wire [15:0]rpm_output
);
reg [31:0] pulse_count;
	reg last_scan_value;
	reg [15:0] pulse_count_qty;
	reg [15:0] output_count_qty;
	reg [15:0] rpm_output;

	always @(posedge clk) begin
		if (pulse_count == 0) begin
			pulse_count <= 50000000 - 1;
		end
		else begin
			pulse_count <= pulse_count - 1;
		end
	end

	always @(posedge clk) begin
		if (pulse_count == 0) begin
			pulse_count_qty <= 0;
			output_count_qty <= 0;
		end
		else begin
			if (motor_rot_pulse == 1 && last_scan_value == 0) begin
				pulse_count_qty <= pulse_count_qty + 1;
			end
			last_scan_value <= motor_rot_pulse;
		end
	end

	always @(posedge clk) begin
		if (pulse_count == 0) begin
			rpm_output <= output_count_qty;
		end
	end

endmodule

