module cycloneii_latch(D, ENA, PRE, CLR, Q);

   input D;
   input ENA, PRE, CLR;
   output Q;
reg q_out;

   buf B1(D, q_out);
   buf B2(ENA, q_out);
   buf B3(PRE, q_out);
   buf B4(CLR, q_out);

   always @(posedge ENA, posedge PRE, posedge CLR) begin
      if (ENA) begin
