	parameter slow_pulse_threshold = 18000000;
	parameter fast_pulse_threshold = 4800000;
	parameter variable_pulse_threshold = 2000000 * (variable_pulse_index / 24000000);

	assign slow_pulse = (counter >= slow_pulse_threshold);
	assign fast_pulse = (counter >= fast_pulse_threshold);
	assign variable_pulse = (counter >= variable_pulse_threshold);

	always @(posedge clk or posedge reset) begin
