module twocmp(input [31:0]A,output [31:0]B);
genvar i;
generate
    for(i=0;i<32;i=i+1)begin:twocmp
        assign B[i]=i==0?A[0]:~(A[0] | A[i-1:i]);
    end
endgenerate
endmodule

module arbiter (
clock, 
reset, 
req_0,
req_1, 
gnt_0,
gnt_1
);

input clock, reset, req_0, req_1;
output gnt_0, gnt_1;
reg gnt_0, gnt_1;

always @(posedge clock) begin
	if (reset) begin
		gnt_0 <= 0;
		gnt_1 <= 0;
	end
	else begin
		if (req_0) begin
			gnt_0 <= 1;
			gnt_1 <= 0;
		end
		else if (req_1) begin
			gnt_0 <= 0;
			gnt_1 <= 1;
		end
	end
end

endmodule

module NAND3C(Y,A,B,C);
 input A,B,C;
 output Y;
not (X1,A);
   not (X2,B);
   and (Y,X1,X2);
   not (X3,C);
   nand (Y,X3,Y);
   specify
     specparam
       tplh$A = 1.0,
       tphl$A = 1.0,
       tplh$B = 1.0,
       tphl$B = 1.0,
       tplh$C = 1.0,
       tphl$C = 1.0;
     (A -=> Y) = (tplh$A,tphl$A);
     (B -=> Y) = (tplh$B,tphl$B);
     (C -=> Y) = (tplh$C,tphl$C);
   endspecify
endmodule

module th22i
    #(parameter INITIAL = 0) (
      input	 init,
      input	 A, 
      input	 B, 
      output reg Q);
always @(A, B)
    begin
      if (init)
        Q <= INITIAL;
      else if (A & B)
        Q <= 1;
      else if (~A & ~B)
        Q <= 0;
    end
endmodule

