module pcm(set,clk,q1,q2,q3);
	input set,clk;
	output q1,q2,q3;
reg [4:0] count;
	always @(posedge clk)
		if(set) count <= 5'b10000;
		else count <= count - 1'b1;
	assign q1 = (count >= 5'b01100) & (count < 5'b10000);
	assign q2 = (count >= 5'b01010) & (count < 5'b01100);
	assign q3 = (count >= 5'b00110) & (count < 5'b01010);
endmodule

