module zmc2_dot(
	input CLK_12M,
	input EVEN,
	input LOAD,
	input H,
	input [31:0] CR,
	output reg [3:0] GAD, GBD,
	output reg DOTA, DOTB
);
reg [3:0] SR;
always @(posedge CLK_12M) begin
	if (LOAD) SR <= CR;
	else begin
		if (H) SR <= {SR[2:0], SR[31]};
		else SR <= {SR[30:1], SR[31]};
	end
end
always @(SR) begin
	if (EVEN) GAD <= SR[3];
	else GAD <= SR[2];
	if (EVEN) GBD <= SR[3];
	else GBD <= SR[2];
end
assign DOTA = GAD | GBD;
assign DOTB = GAD & GBD;
endmodule

