module Bin2BCDConverter_4
#(
	parameter INPUT_BIT_WIDTH  = 8
)
(
    input [(INPUT_BIT_WIDTH-1):0] Input,
    output reg [3:0] Digit3,
    output reg [3:0] Digit2,
    output reg [3:0] Digit1,
    output reg [3:0] Digit0
);
always @ (Input)
    for (integer i = INPUT_BIT_WIDTH-1; i >= 0; i = i - 1)
    begin
        if (Digit3 >= 10)
            Digit3 = Digit3 + 3;
        if (Digit2 >= 10)
            Digit2 = Digit2 + 3;
        if (Digit1 >= 10)
            Digit1 = Digit1 + 3;
        if (Digit0 >= 10)
            Digit0 = Digit0 + 3;
        Digit3 = Digit3 << 1;
        Digit2 = Digit2 << 1;
        Digit1 = Digit1 << 1;
        Digit0 = Digit0 << 1;
        Digit0 = Digit0 | Input[i];
    end
endmodule

