module clock_divider(clock_in,clock_out
    );
input clock_in; 
output reg clock_out;
parameter DIVISOR = 28'd1000000000;
reg [27:0] counter;
always @(posedge clock_in)
begin
    counter <= counter + 1;
    if(counter == DIVISOR - 1)
    begin
        counter <= 0;
    end
end
assign clock_out = (counter < DIVISOR/2) ? 1'b1 : 1'b0;
endmodule

