module noise(
  input i_clk,
  output reg signed [15:0] o_data
);
reg [15:0] r_shift16 = 16'b0xDEAD;
  always @(posedge i_clk) begin
    r_shift16 <= {r_shift16[14:0], r_shift16[15] ^ r_shift16[14] ^ r_shift16[12] ^ r_shift16[3]};
    if (r_shift16 == 16'b0x8000) begin
      o_data <= 16'b0x8001;
    end
    else begin
      o_data <= r_shift16;
    end
  end
endmodule

