module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [9:0] hsize = 1920;
parameter [9:0] vsize = 1080;
parameter [9:0] hfront = 16;
parameter [9:0] hback = 16;
parameter [9:0] vfront = 10;
parameter [9:0] vback = 10;
parameter [9:0] hretrace = 16;
parameter [9:0] vretrace = 16;
reg [9:0] h_count_reg;
reg [9:0] v_count_reg;
reg [9:0] xaddr;
reg [9:0] yaddr;
always @(posedge clk) begin
  if(rst == 1'b1) begin
    h_count_reg <= 10'b0;
    v_count_reg <= 10'b0;
    xaddr <= 10'b0;
    yaddr <= 10'b0;
    active <= 1'b0;
    hsync <= 1'b0;
    vsync <= 1'b0;
  end else begin
    h_count_reg <= h_count_reg + 10'b1;
    v_count_reg <= v_count_reg + 10'b1;
    xaddr <= h_count_reg;
    yaddr <= v_count_reg;
    if(h_count_reg == (hsize + hfront + hback)) begin
      h_count_reg <= 10'b0;
      hsync <= 1'b0;
    end
    else if(h_count_reg == (hsize + hfront + hback + hretrace)) begin
      h_count_reg <= 10'b0;
      hsync <= 1'b1;
    end
    else if(h_count_reg == (hsize + hfront + hback + hretrace + hretrace)) begin
      h_count_reg <= 10'b0;
      hsync <= 1'b0;
    end
    else if(h_count_reg == (hsize + hfront + hback + hretrace + hretrace + hretrace)) begin
      h_count_reg <= 10'b0;
      hsync <= 1'b1;
    end
    else if(v_count_reg == (vsize + vfront + vback)) begin
      v_count_reg <= 10'b0;
      vsync <= 1'b0;
    end
    else if(v_count_reg == (vsize + vfront + vback + vretrace)) begin
      v_count_reg <= 10'b0;
      vsync <= 1'b1;
    end
    else if(v_count_reg == (vsize + vfront + vback + vretrace + vretrace)) begin
      v_count_reg <= 10'b0;
      vsync <= 1'b0;
    end
    else if(v_count_reg == (vsize + vfront + vback + vretrace + vretrace + vretrace)) begin
      v_count_reg <= 10'b0;
      vsync <= 1'b1;
    end
    else begin
      active <= 1'b1;
    end
  end
end
endmodule

