module TopModule(
    input  in,
    input  state,
    output next_state,
    output out
);
parameter [1:0] A = 2'b00;
    parameter [1:0] B = 2'b01;
    parameter [1:0] C = 2'b10;
    parameter [1:0] D = 2'b11;
    reg [1:0] next_state;
    reg out;
    always @ (state or in) begin
        case (state)
            A: begin
                next_state = in ? B : A;
                out = 0;
            end
            B: begin
                next_state = in ? C : B;
                out = 0;
            end
            C: begin
                next_state = in ? A : D;
                out = 0;
            end
            D: begin
                next_state = in ? C : B;
                out = 1;
            end
        endcase
    end
    assign next_state = next_state;
    assign out = out;
endmodule

