    parameter [0:0] A = 1'b1;
    parameter [0:0] B1 = 1'b1;
    parameter [0:0] A1 = 1'b0;
    reg [0:0] state = B;
    always @(posedge clk) begin
        if (areset) begin
            state <= B;
        end else begin
            case (state)
                B: begin
                    if (in == 1'b0) begin
                        state <= A;
                    end
                    else begin
                        state <= B;
                    end
                end
                A: begin
                    if (in == 1'b0) begin
                        state <= B;
                    end
                    else begin
                        state <= A;
                    end
                end
                default: begin
                    state <= B;
                end
            endcase
        end
    end
    assign out = state;
endmodule

module TopModule(
