    input  areset,
    input  j,
    input  k,
    output out
);
parameter OFF = 1'b0;
    parameter ON  = 1'b1;
    reg [1:0] state = OFF;
    always @(posedge clk or posedge areset) begin
        if (areset == 1'b1) begin
            state <= OFF;
        end else begin
            case (state)
                OFF: begin
                    if (j == 1'b0) begin
                        state <= OFF;
                    end else begin
                        state <= ON;
                    end
                end
                ON: begin
                    if (k == 1'b0) begin
                        state <= ON;
                    end else begin
                        state <= OFF;
                    end
                end
            endcase
        end
    end
    assign out = state;
endmodule

