module TopModule(
    input  clk,
    input  aresetn,
    input  x,
    output z
);
parameter [1:0] N = 2;
    reg [1:0] state;
    reg z;
    always @(posedge clk) begin
        if (arstn == 1'b0) begin
            state <= 0;
            z <= 0;
        end else begin
            case (state)
                0: begin
                    if (x == 1'b0) begin
                        state <= 0;
                    end else if (x == 1'b1) begin
                        state <= 1;
                    end
                end
                1: begin
                    if (x == 1'b0) begin
                        state <= 0;
                    end else if (x == 1'b1) begin
                        state <= 2;
                    end
                end
                2: begin
                    if (x == 1'b0) begin
                        state <= 0;
                    end else if (x == 1'b1) begin
                        state <= 1;
                    end
                end
                default: begin
                    state <= 0;
                end
            endcase
            if (state == 2) begin
                z <= 1;
            end else begin
                z <= 0;
            end
        end
    end
endmodule

