    output z
);
parameter [1:0] A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11;
    reg [1:0] state;
    reg z;
    always @(posedge clk) begin
        if (reset) begin
            state <= A;
            z <= 0;
        end else begin
            case (state)
                A: begin
                    if (s) begin
                        state <= B;
                    end
                end
                B: begin
                    if (w) begin
                        z <= 1;
                        state <= C;
                    end
                    else begin
                        z <= 0;
                        state <= D;
