  input b,
  input cin,
  output cout,
  output sum
);
full_adder fa(sum, cout, a, b, cin);
endmodule

module TopModule (
  input d,
  input ena,
  output logic q
);
always@(posedge ena) begin
    q <= d;
  end
endmodule

module TopModule (
  input in1,
  input in2,
  input in3,
  output logic out
);
assign out = in1 ^ in2;
endmodule

module TopModule (
  input [254:0] in,
  output reg [7:0] out
);
always @ (in) begin
    out = 0;
    for (int i = 0; i < 255; i = i + 1) begin
      out = out + in[i];
    end
  end
endmodule

module TopModule (
  input clk,
  input d,
  output reg q
);
always @(posedge clk) begin
    q <= d;
  end
endmodule

