module TopModule (
  input clk,
  input [7:0] d,
  output reg [7:0] q
);
DFF dff1(.clk(clk), .d(d[0]), .q(q[0]));
  DFF dff2(.clk(clk), .d(d[1]), .q(q[1]));
  DFF dff3(.clk(clk), .d(d[2]), .q(q[2]));
  DFF dff4(.clk(clk), .d(d[3]), .q(q[3]));
  DFF dff5(.clk(clk), .d(d[4]), .q(q[4]));
  DFF dff6(.clk(clk), .d(d[5]), .q(q[5]));
  DFF dff7(.clk(clk), .d(d[6]), .q(q[6]));
  DFF dff8(.clk(clk), .d(d[7]), .q(q[7]));
endmodule

module TopModule (
  input ring,
  input vibrate_mode,
  output ringer,
  output motor
);
assign ringer = ring & ~vibrate_mode;
  assign motor = vibrate_mode;
endmodule

module TopModule (
