module TopModule (
  input [3:0] in,
  output out_and,
  output out_or,
  output out_xor
);
wire and_in0, and_in1, and_in2, and_in3;
  wire or_in0, or_in1, or_in2, or_in3;
  wire xor_in0, xor_in1, xor_in2, xor_in3;
  and and0 (out_and, and_in0, and_in1, and_in2, and_in3);
  or or0 (out_or, or_in0, or_in1, or_in2, or_in3);
  xor xor0 (out_xor, xor_in0, xor_in1, xor_in2, xor_in3);
endmodule

module TopModule (
  input [99:0] in,
  output out_and,
  output out_or,
  output out_xor
);
wire [99:0] and;
  wire [99:0] or;
  wire [99:0] xor;

  and_100and and_100and_0 (and[99:0], in[99:0]);
  or_100or or_100or_0 (or[99:0], in[99:0]);
  xor_100xor xor_100xor_0 (xor[99:0], in[99:0]);

  assign out_and = and[99:0];
  assign out_or = or[99:0];
  assign out_xor = xor[99:0];

endmodule

