module TopModule (
  input clk,
  input resetn,
  input in,
  output out
);
reg [3:0] d;
  always @(posedge clk) begin
    if (!resetn) begin
      d <= 4'b0000;
    end
    else begin
      d <= {d[2:0], in};
    end
  end
  assign out = d[3];
endmodule

module TopModule (
  input sel,
  input [7:0] a,
  input [7:0] b,
  output reg [7:0] out
);
always @ (sel)
    out = (~sel & a) | (sel & b);

endmodule

