  input [4:0] f,
  output [7:0] w,
  output [7:0] x,
  output [7:0] y,
  output [7:0] z
);
assign w = {a,b,c,d,e,f};
  assign x = {w[7:0],1'b0};
  assign y = {w[15:8],1'b0};
  assign z = {w[23:16],1'b0};
endmodule

module TopModule (
  input clk,
  input reset,
  output [3:1] ena,
  output reg [15:0] q
);
always @(posedge clk) begin
    if (reset) begin
      q <= 16'b0000000000000000;
    end else begin
      q[15:12] <= q[11:8];
      q[11:8] <= q[7:4];
      q[7:4] <= q[3:0];
      ena[3:1] <= {q[3:0], 1'b0};
    end
  end
endmodule

module TopModule (
  input x3,
  input x2,
  input x1,
  output f
);
assign f = x3 & x2 & x1 | x3 & x2 & ~x1 | x3 & ~x2 & x1 | x3 & ~x2 & ~x1 | ~x3 & x2 & x1 | ~x3 & x2 & ~x1 | ~x3 & ~x2 & x1 | ~x3 & ~x2 & ~x1;
endmodule

module TopModule (
  input [7:0] in,
  output reg [2:0] pos
);
always @ (in) begin
    pos = 0;
    for (int i = 0; i < 8; i = i + 1) begin
      if (in[i] == 1) begin
        pos = i;
        break;
      end
    end
  end
endmodule

module TopModule (
  input mode,
  input too_cold,
  input too_hot,
  input fan_on,
  output heater,
  output aircon,
  output fan
);
assign heater = (mode == 1) && (too_cold == 1) && (aircon == 0) && (fan == 0);
  assign aircon = (mode == 0) && (too_hot == 1) && (heater == 0) && (fan == 0);
  assign fan = (mode == 1) || (mode == 0) || (fan_on == 1);
endmodule

