module TopModule (
  input [2:0] sel,
  input [3:0] data0,
  input [3:0] data1,
  input [3:0] data2,
  input [3:0] data3,
  input [3:0] data4,
  input [3:0] data5,
  output reg [3:0] out
);
always @ (sel)
  begin
    if (sel < 3)
      out = data0;
    else if (sel < 6)
      out = data1;
    else if (sel < 9)
      out = data2;
    else if (sel < 12)
      out = data3;
    else if (sel < 15)
      out = data4;
    else if (sel < 18)
      out = data5;
    else
      out = 4'b0000;
  end
endmodule

module TopModule (
