);
wire and1_out;
  wire and2_out;
  wire or1_out;

  and and1 (and1_out, a, b);
  and and2 (and2_out, c, d);
  or or1 (or1_out, and1_out, and2_out);
  not not1 (out_n, or1_out);
  assign out = or1_out;

endmodule

module TopModule (
  input in,
  input [3:0] state,
  output reg [3:0] next_state,
  output out
);
always @ (state or in) begin
    case (state)
      4'b0001: begin
        next_state = 4'b0001;
        out = 1'b0;
      end
      4'b0010: begin
        next_state = 4'b0010;
        out = 1'b0;
      end
      4'b0100: begin
        next_state = 4'b0100;
        out = 1'b0;
      end
      4'b1000: begin
        next_state = 4'b1000;
        out = 1'b1;
      end
      default: begin
        next_state = 4'b0001;
        out = 1'b0;
      end
    endcase
  end
endmodule

