  reg [N-1:0] state;
  reg [N-1:0] next_state;
  wire [N-1:0] one_hot;
  assign one_hot = state;
  assign z = one_hot[0];
  always @(posedge clk) begin
    if (areset) begin
      state <= 0;
    end else begin
      state <= next_state;
    end
  end
  always @(*) begin
    next_state = state;
    case (state)
      0: begin
        if (x == 0) begin
          next_state = 0;
        end else begin
          next_state = 1;
        end
      end
      1: begin
        if (x == 0) begin
          next_state = 1;
        end else begin
          next_state = 0;
        end
      end
    endcase
  end
endmodule

