  reg [1:0] Y4;
  always @ (y or w) begin
    case (y[5:0])
      6'b000001: begin
        Y2 <= 2'b00;
        Y4 <= 2'b00;
      end
      6'b000010: begin
        Y2 <= 2'b01;
        Y4 <= 2'b00;
      end
      6'b000100: begin
