      6'b100000: begin
        Y2 <= 2'b01;
        Y4 <= 2'b01;
      end
      default: begin
        Y2 <= 2'b00;
        Y4 <= 2'b00;
      end
    endcase
  end
  assign Y1 = Y2[0];
  assign Y3 = Y4[0];
endmodule

